    """Extract the content between the first <answer>...</answer> tags."""
    match = ANSWER_PATTERN.search(text)
    if match:
        return match.group(1).strip()
    return None


def parse_question_output_type(question: str) -> str | None:
    """Extract the expected output/return type from the question text.

    Handles patterns like:
      Output: `return` (tuple)
      Output: `return` (list)
      Output: `return` (dict)
      Output: `return` (float)
      Output: `return` (int)
      Output: `return` (bool)
      Output: `return` (string)
      Output: `return` (list of int)
      Output: `return` (list of tuples)
      Output: `return` (list of int)
    """
    # Try multiple patterns
    patterns = [
        r"Output:\s*`return`\s*\(\s*list of (\w+)",
        r"Output:\s*`return`\s*\(\s*(tuple|list|dict|float|int|string|bool)",
        r"Output:\s*\(\s*(tuple|list|dict|float|int|string|bool)",
        r"Output:\s*`return`\s*\(\s*list of tuples",
        r"Output:\s*`return`\s*\(\s*list of int",
        r"Output:\s*`return`\s*\(\s*list of float",
        r"Output:\s*`return`\s*\(\s*list of bool",
    ]
    for pat in patterns:
        m = re.search(pat, question, re.IGNORECASE)
        if m:
            if "list of tuples" in pat:
                return "list_of_tuples"
            if "list of int" in pat:
                return "list_of_ints"
            if "list of float" in pat:
                return "list_of_floats"
            if "list of bool" in pat:
                return "list_of_bools"
            return m.group(1).lower()
    return None


def parse_question_input_keys(question: str) -> list[str] | None:
    """Extract expected input variable keys from the question."""
    keys = []
    m = re.search(r"Input:\s*\n(.*?)(?:\n\n|\nOutput:)", question, re.DOTALL)
    if m:
        input_section = m.group(1)
        key_patterns = [
            r"`(\w+)`\s*\([^)]*\):",
            r"\b(\w+)\s*\(int\|float\|str\|bool\):",
        ]
        for pat in key_patterns:
            keys.extend(re.findall(pat, input_section))
        # Also try a more general pattern
        if not keys:
            for line in input_section.split('\n'):
                km = re.match(r'\s*`(\w+)`', line)
                if km:
                    keys.append(km.group(1))
