Improved harness for codeio tasks with:
1. Structured inverse-task prompting (Proposal 3)
2. Python-literal parsing with type coercion (Proposal 2)
3. Schema-aware retry loop (Proposal 2 + 3)
"""

import re
import json
import ast
from collections import Counter

from harness_evolve.llm import llm_acall

SYSTEM_PROMPT = (
    "You are solving a code I/O prediction task. "
    "Solve step by step using this strategy:\n"
    "1. Identify the reference code's main_solution function and its inputs/outputs.\n"
    "2. For inverse tasks (given output, find input): derive constraints that produce the target output.\n"
    "3. For forward tasks (given input, find output): trace the code execution carefully.\n"
    "4. For stochastic code (np.random, random): choose specific parameter values;\n"
    "   the verifier uses partial matching and tolerance.\n"
    "5. For tasks with multiple input variables, your answer MUST be a JSON object\n"
    "   with keys exactly matching the input variable names (e.g., {\"key1\": val1, \"key2\": val2}).\n\n"
    "Output Format Rules:\n"
    "- Wrap your final answer in <answer> tags on its own line.\n"
    "- For inverse tasks: output a JSON object {\"input_var1\": val, ...}\n"
    "- For forward tasks: output the exact value (dict, list, tuple, scalar) as specified.\n"
    "- For tuple outputs: use Python syntax (a, b) OR JSON array [a, b] (we coerce).\n"
    "- Preserve float precision. Avoid rounding unless specified.\n"
    "- Do NOT include any text outside the <answer> tags.\n"
    "- Do NOT include markdown code blocks.\n"
)

RETRY_SYSTEM_PROMPT = (
    "You are solving a code I/O prediction task. "
    "Your previous answer failed verification. Read the error carefully and provide a corrected answer. "
    "Solve step by step, then wrap your final answer in <answer> tags.\n"
    "- For inverse tasks: output a JSON object with keys matching input variable names.\n"
    "- For forward tasks: output the exact value as specified.\n"
    "- Do NOT include any text outside the <answer> tags.\n"
)


ANSWER_PATTERN = re.compile(r'<answer>(.*?)</answer>', re.DOTALL | re.IGNORECASE)


def extract_answer(text: str) -> str | None:
    """Extract the content between the first <answer>...</answer> tags."""
    match = ANSWER_PATTERN.search(text)
    if match:
        return match.group(1).strip()
    return None


def try_parse_json(text: str):
    """Try to parse text as JSON. Returns (parsed_obj, None) or (None, error_msg)."""
    try:
        return json.loads(text), None
    except json.JSONDecodeError as e:
        return None, f"JSON parse error: {str(e)}"


def try_parse_python_literal(text: str):
    """Try to parse text as a Python literal. Returns (parsed_obj, None) or (None, error_msg)."""
    try:
        return ast.literal_eval(text), None
    except (ValueError, SyntaxError) as e:
        return None, f"Python literal parse error: {str(e)}"


def try_parse_any(text: str):
    """Try JSON first, then Python literal. Returns (parsed_obj, source, error)."""
    # Try JSON first (handles dicts, lists, numbers, strings, bools, null)
    parsed, err = try_parse_json(text)
    if parsed is not None:
        return parsed, "json", None

    # Try Python literal (handles tuples, sets, etc.)
    parsed, err = try_parse_python_literal(text)
    if parsed is not None:
        return parsed, "python", None

    return None, None, err


def parse_question_output_type(question: str) -> str | None:
    """Extract the expected output type from the question text."""
    m = re.search(r"Output:\s*`return`\s*\((\w+)", question)
    if m:
        return m.group(1).strip()
    return None


def parse_question_input_keys(question: str) -> list[str]:
    """Extract the expected input variable keys from the question text."""
    keys = []
    # Match patterns like: `key_name` (type): description
    m = re.findall(r"`(\w+)`\s*\(\s*\w+\s*\)", question)
    if m:
        keys = m
    else:
        # Try Input section patterns
        input_section = re.search(r'Input:\s*\n((?:\s+`[^`]+`.*?\n)+)', question, re.DOTALL)
        if input_section:
            keys = re.findall(r"`(\w+)`", input_section.group(1))
    return keys


def coerce_type(value, expected_type: str | None):
    """Coerce a parsed value to the expected Python type if possible."""
    if expected_type is None:
        return value

    if expected_type == "tuple":
        if isinstance(value, list):
            return tuple(value)
        if isinstance(value, tuple):
            return value

    if expected_type == "dict":
        if isinstance(value, dict):
            return value

    return value


def validate_schema(answer_value, expected_keys: list[str], task_id: str):
    """
    Validate that the answer has the correct schema.
    For inverse tasks (dict output), check that keys match expected input keys.
    Returns (is_valid, error_message).
    """
    if not expected_keys:
        return True, None

    if isinstance(answer_value, dict):
        answer_keys = set(answer_value.keys())
        expected_key_set = set(expected_keys)

        # Check for extra keys
        extra_keys = answer_keys - expected_key_set
        if extra_keys:
            return False, f"Extra keys in output: {extra_keys}. Expected only: {expected_keys}"

        # Check for missing keys
        missing_keys = expected_key_set - answer_keys
        if missing_keys:
            return False, f"Missing keys in output: {missing_keys}. Expected: {expected_keys}"

        return True, None

    elif isinstance(answer_value, (int, float, str, bool, type(None))):
        # Scalar value where a dict was expected
        return False, (
            f"Expected a JSON object with keys {expected_keys}, "
            f"but got a scalar value: {answer_value}. "
            f"Wrap your answer as a dict: {{\"{expected_keys[0]}\": your_value}}"
        )

    elif isinstance(answer_value, list):
        # Check if it's a list where a dict was expected
        if not answer_value:
            return False, f"Expected a JSON object with keys {expected_keys}, but got an empty list."
        return False, (
            f"Expected a JSON object with keys {expected_keys}, "
            f"but got a list with {len(answer_value)} items. "
            f"Your answer should be a dict like: {{{expected_keys[0]}: value}}"
        )

    return True, None


def format_as_json_safe(value) -> str:
    """Convert a Python value to a JSON-safe string for output."""
    # Convert tuples to lists for JSON
    def convert(val):
        if isinstance(val, tuple):
            return [convert(item) for item in val]
        if isinstance(val, dict):
            return {k: convert(v) for k, v in val.items()}
        if isinstance(val, list):
            return [convert(item) for item in val]
        # Handle special float types from numpy etc.
        if isinstance(val, (float,)):
            # Check for NaN/Inf
            if val != val:  # NaN check
                return None
            if val == float('inf'):
                return None
            if val == float('-inf'):
                return None
        return val

    converted = convert(value)
    return json.dumps(converted, separators=(', ', ': '))


async def solve(model, question, **kwargs) -> dict:
